mapper.select:
SELECT b.reason AS reason, COUNT(*) AS cnt
FROM `task_dispatch_block` b
WHERE b.checked_at >= #{from}
  AND b.checked_at < #{to}
GROUP BY b.reason

SELECT COUNT(DISTINCT DATE_FORMAT(b.checked_at, '%Y-%m-%d %H'))
FROM `task_dispatch_block` b
WHERE b.checked_at >= #{from}
  AND b.checked_at < #{to}

SELECT c.task_id AS taskId, c.seq AS seq, c.deviation_m AS deviationM
FROM `task_checkin` c
JOIN `task` t ON t.id = c.task_id
WHERE t.actual_end_time IS NOT NULL
  AND t.actual_end_time >= #{from}
  AND t.actual_end_time < #{to}
